import React, { useState, useContext } from 'react';
import { TripContext } from '../context/TripContext';

const FamilyList = () => {
  const { families, setFamilies } = useContext(TripContext);
  const [head, setHead] = useState('');
  const [numMembers, setNumMembers] = useState(0);
  const [memberNames, setMemberNames] = useState([]);

  const handleAddFamily = () => {
    const members = memberNames.filter(name => name.trim() !== '');
    if (!head || members.length !== parseInt(numMembers)) return;

    const newFamily = { head, members };
    setFamilies(prev => [...prev, newFamily]);

    // Reset
    setHead('');
    setNumMembers(0);
    setMemberNames([]);
  };

  const handleNumMembersChange = (e) => {
    const count = parseInt(e.target.value);
    setNumMembers(count);
    setMemberNames(new Array(count).fill(''));
  };

  const handleMemberNameChange = (index, value) => {
    const updated = [...memberNames];
    updated[index] = value;
    setMemberNames(updated);
  };

  return (
    <div>
      <h3>Add Family</h3>
      <input placeholder="Family Head" value={head} onChange={e => setHead(e.target.value)} />
      <input type="number" placeholder="Number of Members" value={numMembers} onChange={handleNumMembersChange} />
      {memberNames.map((name, idx) => (
        <input
          key={idx}
          placeholder={`Member ${idx + 1}`}
          value={name}
          onChange={e => handleMemberNameChange(idx, e.target.value)}
        />
      ))}
      <button onClick={handleAddFamily}>Add Family</button>
    </div>
  );
};

export default FamilyList;
